// 整数・実数・真偽値を整数へ変換し、その他の型では空を返す。
// 実数の有限性・整数範囲の検査は、この関数では行わない。
std::optional<Integer> value_integer(const Value& value)
{
    if (const auto* integer = std::get_if<Integer>(&value.storage())) return *integer;
    if (const auto* real = std::get_if<::cw::lib::Real>(&value.storage())) return static_cast<Integer>(*real);
    if (const auto* boolean = std::get_if<bool>(&value.storage())) return *boolean ? 1 : 0;
    return std::nullopt;
}

std::optional<String> value_string(const Value& value)
{
    if (const auto* string = std::get_if<String>(&value.storage())) return *string;
    return std::nullopt;
}

template <typename T>
std::shared_ptr<T> object_value(const Value& value)
{
    const auto* object = std::get_if<ObjectPtr>(&value.storage());
    return object ? std::dynamic_pointer_cast<T>(*object) : nullptr;
}

std::vector<String> choice_strings(const Value& value)
{
    std::vector<String> choices;
    const auto sequence = object_value<::cw::data::VariantSequence>(value);
    if (!sequence) {
        if (const auto text = value_string(value)) choices.push_back(*text);
        return choices;
    }
    choices.reserve(sequence->m_values.size());
    for (const auto& item : sequence->m_values) {
        if (const auto text = value_string(item)) {
            choices.push_back(*text);
            continue;
        }
        // この関数では(label, bitmap)の先頭ラベルを抽
        // 出する。画像はchoice_bitmapsで別に取得する。
        const auto row = object_value<::cw::data::VariantSequence>(item);
        if (row && !row->m_values.empty()) {
            if (const auto label = value_string(row->m_values.front())) choices.push_back(*label);
        }
    }
    return choices;
}

std::vector<std::shared_ptr<::cw::lib::Bitmap>> choice_bitmaps(const Value& value)
{
    std::vector<std::shared_ptr<::cw::lib::Bitmap>> bitmaps;
    const auto sequence = object_value<::cw::data::VariantSequence>(value);
    if (!sequence) return bitmaps;
    bitmaps.reserve(sequence->m_values.size());
    for (const auto& item : sequence->m_values) {
        const auto row = object_value<::cw::data::VariantSequence>(item);
        if (!row || row->m_values.size() < 2) {
            bitmaps.push_back(nullptr);
            continue;
        }
        bitmaps.push_back(object_value<::cw::lib::Bitmap>(row->m_values[1]));
    }
    return bitmaps;
}

Integer clamp_integer(Integer value, Integer minimum, Integer maximum)
{
    if (maximum < minimum) maximum = minimum;
    return std::clamp(value, minimum, maximum);
}



Integer parse_event_integer(const String& value, Integer fallback = 0)
{
    try {
        std::size_t used = 0;
        const auto parsed = std::stoll(value, &used);
        return used == value.size() ? static_cast<Integer>(parsed) : fallback;
    } catch (const std::exception&) {
        return fallback;
    }
}

