struct ComboMessageLayout {
    ::cw::lib::ui::FontStyle message,choice,button;
    std::vector<String> lines;
    Integer width{},height{},text_width{},text_height{},line_height{};
    ::cw::lib::Rect choice_rect,accept,cancel;
};
ComboMessageLayout combo_message_layout(const String& message) {
    namespace input=::cw::dialog::input_presentation;
    ComboMessageLayout out;
    out.message=::cw::lib::ui::configured_wx_font("dlgmsg",15);
    out.choice=::cw::lib::ui::configured_wx_font("combo",16);
    out.button=::cw::lib::ui::configured_wx_font("button",14);
    out.lines=input::lines(message);out.line_height=input::cell_height(out.message);
    for(const auto& line:out.lines)out.text_width=std::max(out.text_width,input::text_width(line,out.message));
    out.text_height=out.line_height*static_cast<Integer>(out.lines.size());
    out.width=input::px(318);
    const Integer choice_height=std::max(input::px(24),input::cell_height(out.choice)+input::px(6));
    out.choice_rect={(out.width-input::px(200))/2,input::px(20)+out.text_height,input::px(200),choice_height};
    const Integer margin=(out.width-2*input::px(100))/3;
    const Integer button_y=out.choice_rect.y+choice_height+input::px(10);
    out.accept={margin,button_y,input::px(100),input::px(30)};
    out.cancel={2*margin+input::px(100),button_y,input::px(100),input::px(30)};
    out.height=button_y+input::px(40);
    return out;
}

void step_number_editor(const std::shared_ptr<NumberEditor>& editor, Integer delta)
{
    if (!editor || !editor->m_slider) return;
    if (delta < 0) editor->m_slider->OnLeftBtn(nullptr);
    else editor->m_slider->OnRightBtn(nullptr);
    editor->OnSlider(Value{});
}

