void BackColorEditDialog::update_panels()
{
    const auto rgb = hsv2rgb(m_hsv);
    EditUiSpec spec;
    spec.kind = EditUiKind::back_color;
    spec.title = edit_message("edit_bgcolor", "Back color");
    spec.choices.reserve(m_presetcolor_names.size());
    for (const auto& name : m_presetcolor_names) spec.choices.push_back(value_string(name).value_or(String{}));
    spec.values = {m_preset_selection};
    spec.rgb = {std::get<0>(rgb), std::get<1>(rgb), std::get<2>(rgb)};
    spec.hsv = {std::get<0>(m_hsv),std::get<1>(m_hsv),std::get<2>(m_hsv)};
    spec.panel_focus = {m_is_select_huepanel, m_is_select_saturationpanel, m_is_select_valuepanel};
    get_edit_ui_backend()->update(spec);
}

