// Python はプリセット名が一致するたびに再描画し、最
// 後の一致が残る。 最後の一致を一度だけ選び、重複名でも同
// じ最終 RGB にしつつ、途中の色の公開・描画を省く。
void BackColorEditDialog::OnChoicePreset(std::shared_ptr<::cw::lib::Window> arg_evt)
{
    const auto index = arg_evt ? arg_evt->id : m_preset_selection;
    m_preset_selection = index;
    if (index <= 0 || index > static_cast<::cw::lib::Integer>(m_presetcolor_list.size())) return;
    // Python と同様、BackColors.xml で最後に一致した名前を採用する。
    const auto& selected_name = std::get<0>(m_presetcolor_list[static_cast<std::size_t>(index - 1)]);
    const auto preset = std::find_if(m_presetcolor_list.rbegin(), m_presetcolor_list.rend(),
        [&](const auto& entry) { return std::get<0>(entry) == selected_name; });
    m_hsv = rgb2hsv({std::get<1>(*preset), std::get<2>(*preset), std::get<3>(*preset)});
    update_panels();
}

