void ComboEditDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, ::cw::lib::String arg_title, ::cw::lib::String arg_label, std::vector<::cw::lib::String> arg_mlist, ::cw::lib::Integer arg_selected)
{
    m_choices=std::move(arg_mlist);
    m_choice_bitmaps.clear();
    m_selected=arg_selected;
    auto combo = std::make_shared<::cw::lib::Window>();
    combo->id = arg_selected >= 0 && arg_selected < static_cast<Integer>(m_choices.size()) ? arg_selected : -1;
    m_combo = combo;
    _do_layout(); _bind();
    EditUiSpec spec; spec.kind = EditUiKind::combo; spec.parent_handle = arg_parent ? arg_parent->native_handle : 0; spec.title = std::move(arg_title); spec.labels = {std::move(arg_label)}; spec.choices = m_choices; spec.choice_bitmaps = m_choice_bitmaps; spec.values = {m_selected};
    get_edit_ui_backend()->create(spec, [this](Integer action, const String& payload) {
        if (action == 0) OnCancel(nullptr);
        else if (action == 1) OnOk(nullptr);
        else if (action == 6 && m_combo) m_combo->id = parse_event_integer(payload, m_combo->id);
    });
}

void ComboEditDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, ::cw::lib::String arg_title, ::cw::lib::String arg_label, ::cw::lib::Value arg_mlist, ::cw::lib::Integer arg_selected)
{
    m_choices = choice_strings(arg_mlist);
    m_choice_bitmaps = choice_bitmaps(arg_mlist);
    m_selected = m_choices.empty() ? -1 : (arg_selected<0?-1:std::clamp<Integer>(arg_selected, 0, static_cast<Integer>(m_choices.size() - 1)));
    auto combo = std::make_shared<::cw::lib::Window>();
    combo->id = m_selected;
    m_combo = combo;
    _do_layout();
    _bind();
    EditUiSpec spec;
    spec.kind = EditUiKind::combo;
    spec.parent_handle = arg_parent ? arg_parent->native_handle : 0;
    spec.title = std::move(arg_title);
    spec.labels = {std::move(arg_label)};
    spec.choices = m_choices;
    spec.choice_bitmaps = m_choice_bitmaps;
    spec.values = {m_selected};
    get_edit_ui_backend()->create(spec, [this](Integer action, const String& payload) {
        if (action == 0) OnCancel(nullptr);
        else if (action == 1) OnOk(nullptr);
        else if (action == 6 && m_combo) m_combo->id = parse_event_integer(payload, m_combo->id);
    });
}

