void InputTextDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, ::cw::lib::String arg_title, ::cw::lib::String arg_msg, ::cw::lib::String arg_text, ::cw::lib::Integer arg_maxlength, ::cw::lib::String arg_addition, std::optional<::cw::lib::Callback> arg_addition_func)
{
    dialog_retained_surface().reset();
    ++m_input_generation;m_addition_running=false;
    m_presentation_finished = false;
    m_presentation_accepted = false;
    m_title = std::move(arg_title);
    m_msg=::cw::util::txtwrap(arg_msg,6,30,"",true,nullptr);m_maxlength=arg_maxlength;
    // SetValue はプログラムからの設定なので、wx の通常の EDIT と同様、ユーザー入力の上限を超えた値も保持する。
    m_edit.reset(std::move(arg_text),true);
    m_focus=0;m_dragging=false;m_modifiers=0;m_edit_menu.close();
    m_addition=std::move(arg_addition);m_addition_func=std::move(arg_addition_func);
    m_textctrl=std::make_shared<::cw::lib::Window>();
    m_text.clear();
    set_window_text(m_textctrl,m_edit.text);
    m_ok_enabled=!m_edit.text.empty();
    _do_layout();_bind();
    // 共通モデルを一つだけ使い、配置とモーダルの所有関係はホストに委ねる。
    (void)arg_parent;
}

void InputTextDialog::sync_input()
{
    const auto& value=m_textctrl?m_textctrl->title:m_text;
    if(value!=m_edit.text) {
        m_edit.reset(value,false,false);
        m_edit_menu.close();m_dragging=false;
    }
    publish_input();
}

void InputTextDialog::publish_input()
{
    m_text=m_edit.text;set_window_text(m_textctrl,m_text);m_ok_enabled=!m_text.empty();
}

