void InputTextDialog::OnInput(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    sync_input();
    m_edit.composition.clear();
    request_dialog_presentation_refresh();
}

void InputTextDialog::OnAddition(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!m_addition_func) throw std::logic_error("addition callback is required");
    sync_input();
    const auto generation=m_input_generation;
    const bool was_running=m_addition_running;
    // 実行中にモデルを閉じたり再初期化したりする可能性があるため、呼び出し可能オブジェクトをコピーする。
    const auto callback=*m_addition_func;
    m_addition_running=true;m_edit_menu.close();m_dragging=false;
    request_dialog_presentation_refresh();
    Value result;
    try {result=callback({},{});}
    catch(...) {
        if(m_input_generation==generation) {m_addition_running=was_running;request_dialog_presentation_refresh();}
        throw;
    }
    // Py の wx 所有コントロールと異なり、ネイティブのモデルはコールバックか
    // ら再初期化できる。 置き換え済み・終了済みのモデルへ古い結果を書き込まない。
    if(m_presentation_finished || m_input_generation!=generation) return;
    m_addition_running=was_running;
    const auto text=value_string(result);
    if (!text) throw std::invalid_argument("Text addition must return a string");
    const auto& value=*text;
    // Python と同様、SelectAll ではなく SetValue を使う。 値が
    // 変わったらキャレットと履歴をリセットし、同じ値なら現在のキャレットと選択を維持する。
    if(value!=m_edit.text) m_edit.reset(value,false,false);
    publish_input();
    request_dialog_presentation_refresh();
}

void InputTextDialog::OnOk(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    sync_input();
    ++m_input_generation;m_edit_menu.close();m_dragging=false;
    m_presentation_accepted=true;m_presentation_finished=true;
    request_dialog_presentation_refresh();
}

void InputTextDialog::OnCancel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if(m_presentation_finished) return;
    ++m_input_generation;m_addition_running=false;m_edit_menu.close();m_dragging=false;
    m_edit.reset({});publish_input();
    m_presentation_accepted=false;m_presentation_finished=true;
    request_dialog_presentation_refresh();
}

void InputTextDialog::OnPaint(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
}

