void LevelEditDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, std::vector<std::shared_ptr<::cw::character::Player>> arg_mlist, ::cw::lib::Integer arg_selected, std::optional<std::shared_ptr<::cw::data::Party>> arg_party)
{
    m_modal_finished = false;
    m_modal_result_ok = false;
    m_list_typed = std::move(arg_mlist);
    m_party_typed = std::move(arg_party);
    m_targets.clear();
    m_targets.emplace_back("全員");
    for (const auto& ccard : m_list_typed) {
        if (!ccard) throw std::invalid_argument("Level target must be a player");
        m_targets.push_back(ccard->get_name());
    }
    const auto selection=std::max<Integer>(arg_selected,-1)+1;
    m_target_index=selection<static_cast<Integer>(m_targets.size()) ? selection : -1;
    auto target = std::make_shared<::cw::lib::Window>();
    target->id = m_target_index;
    target->title = m_target_index<0 ? String{} : m_targets[static_cast<std::size_t>(m_target_index)];
    m_target = Value(std::static_pointer_cast<ObjectPtr::element_type>(target));
    m_slider = std::make_shared<NumberEditor>();
    m_slider->initialize(nullptr, get_maxlevel(), 1, get_maxlevel(), 2);
    _select_target();
    _do_layout(); _bind();
    EditUiSpec spec; spec.kind = EditUiKind::level; spec.parent_handle = arg_parent ? arg_parent->native_handle : 0; spec.title = edit_message("regulate_level_title", "Level"); spec.choices = m_targets; spec.values = {m_target_index, m_slider ? m_slider->get_value() : 1}; spec.minimums = {0, 1}; spec.maximums = {static_cast<Integer>(m_list_typed.size()), get_maxlevel()}; spec.pages = {0, 2};
    get_edit_ui_backend()->create(spec, [this](Integer action, const String& payload) {
        if (m_modal_finished) return;
        if (action == 0) OnCancel(nullptr);
        else if (action == 1) OnOk(nullptr);
        else if (action == 4) OnLeftBtn(nullptr);
        else if (action == 5) OnRightBtn(nullptr);
        else if (action == 6) { auto event = std::make_shared<::cw::lib::Window>(); event->id = parse_event_integer(payload, m_target_index); if (event->id >= 0 && event->id <= static_cast<Integer>(m_list_typed.size())) event->title = m_targets[static_cast<std::size_t>(event->id)]; OnSelectTarget(std::move(event)); }
        else if (action == 8 && m_slider) m_slider->set_value(parse_event_integer(payload, m_slider->get_value()));
    });
}

std::vector<std::shared_ptr<::cw::character::Player>> LevelEditDialog::get_selected()
{
    const auto index = [&]() {
        if (const auto target = object_value<::cw::lib::Window>(m_target)) return target->id;
        return m_target_index;
    }();
    if (index <= 0) return m_list_typed;
    if (index > static_cast<Integer>(m_list_typed.size())) return {};
    return {m_list_typed[static_cast<std::size_t>(index - 1)]};
}

::cw::lib::Integer LevelEditDialog::get_currentlevel()
{
    const auto selected = get_selected();
    std::optional<Integer> level;
    for (const auto& ccard : selected) {
        if (!ccard) continue;
        if (!level) level = ccard->m_level;
        else if (*level != ccard->m_level) { level.reset(); break; }
    }
    return level.value_or(get_maxlevel());
}

::cw::lib::Integer LevelEditDialog::get_maxlevel()
{
    Integer maxvalue = 0;
    for (const auto& ccard : get_selected()) if (ccard) maxvalue = std::max(maxvalue, ccard->get_limitlevel());
    return maxvalue;
}

void LevelEditDialog::_select_target()
{
    if (const auto target = object_value<::cw::lib::Window>(m_target)) m_target_index = target->id;
    if (m_slider) {
        m_slider->set_max(get_maxlevel());
        m_slider->set_value(get_currentlevel());
    }
    EditUiSpec spec; spec.kind = EditUiKind::level; spec.title = edit_message("regulate_level_title", "Level"); spec.choices = m_targets; spec.values = {m_target_index, m_slider ? m_slider->get_value() : 1}; spec.minimums = {0, 1}; spec.maximums = {static_cast<Integer>(m_list_typed.size()), get_maxlevel()}; spec.pages = {0, 2}; get_edit_ui_backend()->update(spec);
}

void LevelEditDialog::_bind()
{
    m_cwpy_debug = false;
}

void LevelEditDialog::_do_layout()
{
    // Py はここで wx のサイザーを設定する。共通の EditUiKind::level
    // 表示はモデルから配置を計算するため、 ここではネイティブ
    // のサイザー状態を保持せず、配置処理で選択対象を変えない。
}

void LevelEditDialog::OnSelectTarget(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_modal_finished) return;
    if (arg_event) {
        m_target_index = std::clamp<Integer>(arg_event->id, 0, static_cast<Integer>(m_list_typed.size()));
        m_target = Value(std::static_pointer_cast<ObjectPtr::element_type>(arg_event));
    }
    _select_target();
}

void LevelEditDialog::OnLeftBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_modal_finished) return;
    (void)arg_event;
    auto index = m_target_index;
    index = index <= 0 ? static_cast<Integer>(m_list_typed.size()) : index - 1;
    m_target_index = index;
    if (const auto target = object_value<::cw::lib::Window>(m_target)) { target->id = index; target->title = m_targets[static_cast<std::size_t>(index)]; }
    _select_target();
}

void LevelEditDialog::OnRightBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_modal_finished) return;
    (void)arg_event;
    auto index = m_target_index;
    index = static_cast<Integer>(m_list_typed.size()) <= index ? 0 : index + 1;
    m_target_index = index;
    if (const auto target = object_value<::cw::lib::Window>(m_target)) { target->id = index; target->title = m_targets[static_cast<std::size_t>(index)]; }
    _select_target();
}

void LevelEditDialog::OnPaint(std::shared_ptr<::cw::lib::Window> arg_evt)
{
    (void)arg_evt;
}

void LevelEditDialog::OnOk(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_modal_finished) return;
    m_modal_finished = true;
    const auto level = m_slider ? m_slider->get_value() : get_currentlevel();
    const auto selected = get_selected();
    const auto party = m_party_typed;
    m_modal_result_ok = queue_edit_on_game_thread([selected, level, party] {
        bool updated_card = false;
        for (const auto& ccard : selected) {
            if (!ccard) continue;
            const auto clevel = std::min(level, ccard->get_limitlevel());
            if (ccard->m_level == clevel) continue;
            ccard->set_level(clevel, true, false, party, true);
            if (const auto card = dynamic_cast<::cw::sprite::card::PlayerCard*>(ccard.get());
                card && card->has_cardimg()) {
                updated_card = true;
                play_edit_sound("harvest");
                const auto card_owner = std::shared_ptr<::cw::sprite::card::PlayerCard>(ccard, card);
                const auto sprite = std::static_pointer_cast<::cw::sprite::base::CWPySprite>(card_owner);
                ::cw::animation::animate_sprite(sprite, "hide");
                if (const auto image = card->get_cardimg()) image->set_levelimg(card->m_level);
                card->update_image(true, std::nullopt);
                ::cw::animation::animate_sprite(sprite, "deal");
            }
        }
        if (!updated_card) play_edit_sound("harvest");
    }, m_on_complete);
    get_edit_ui_backend()->close();
}

void LevelEditDialog::OnCancel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_modal_finished) return;
    m_modal_finished = true;
    play_edit_sound("click");
    get_edit_ui_backend()->close();
}

void MoneyEditPanel::initialize(std::shared_ptr<::cw::dialog::edit::PartyEditor> arg_parent, std::shared_ptr<::cw::data::Party> arg_party)
{
    (void)arg_parent;
    m_party = arg_party ? Value(std::static_pointer_cast<ObjectPtr::element_type>(arg_party)) : Value{};
    if (!arg_party) {
        m_value = Integer{};
        return;
    }

    const auto party_money = arg_party->m_money;
    auto yado_money = ::cw::data::YadoData::s_money;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata)
        yado_money = (*::cw::g_cwpy->m_ydata)->m_money;
    Integer maxvalue = party_money + yado_money;
    Integer minvalue = 0;
    if (maxvalue > ::cw::lib::money::maximum) {
        minvalue = maxvalue - ::cw::lib::money::maximum;
        maxvalue = ::cw::lib::money::maximum;
    }
    m_spin_min=minvalue;m_spin_max=maxvalue;
    m_value = party_money;
    m_spinctrl = party_money;
    m_spinctrl2 = yado_money;
    m_slider = std::make_shared<SliderWithButton>();
    m_slider->initialize(nullptr, party_money, minvalue, maxvalue, 1000, 150);
    m_slider_update_lifetime=std::make_shared<int>(0);
    m_slider->m_on_slider_updated=[this, lifetime=std::weak_ptr<int>(m_slider_update_lifetime)] {
        if (!lifetime.expired()) OnSlider(nullptr);
    };
    _do_layout();
    _bind();
}

void MoneyEditPanel::_bind()
{
    if (m_slider) m_slider->enable();
}

void MoneyEditPanel::OnSlider(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!m_slider) return;
    const auto value = m_slider->m_value;
    m_spinctrl = value;
    m_spinctrl2 = m_spin_max + m_spin_min - value;
    m_value = value;
    m_slider->enable();
}

void MoneyEditPanel::OnSpinCtrl(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!m_slider) return;
    if (arg_event) m_spinctrl = clamp_integer(arg_event->id, m_spin_min, m_spin_max);
    m_slider->set_value(value_integer(m_spinctrl).value_or(m_slider->m_value));
    const auto value = m_slider->m_value;
    m_spinctrl = value;
    m_spinctrl2 = m_spin_max + m_spin_min - value;
    m_value = value;
    m_slider->enable();
}

void MoneyEditPanel::OnSpinCtrl2(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!m_slider) return;
    if (arg_event) m_spinctrl2 = clamp_integer(arg_event->id, m_spin_min, m_spin_max);
    const auto yado_value = value_integer(m_spinctrl2).value_or(m_slider->m_minvalue);
    const auto value = m_spin_max + m_spin_min - yado_value;
    m_slider->set_value(value);
    m_spinctrl = m_slider->m_value;
    m_value = m_slider->m_value;
    m_slider->enable();
}

void MoneyEditPanel::_do_layout()
{
    m_text_party = edit_message("party_money", "Party money");
    m_text_yado = edit_message("base_money", "Inn money");
}

