    _do_layout(); _bind();
    EditUiSpec spec; spec.kind = EditUiKind::number2; spec.parent_handle = arg_parent ? arg_parent->native_handle : 0; spec.title = std::move(arg_title); spec.labels = {arg_label1, arg_label2}; spec.values = {m_value1, m_value2}; spec.minimums = {arg_minvalue1, arg_minvalue2}; spec.maximums = {arg_maxvalue1, arg_maxvalue2}; spec.pages = {arg_page1, arg_page2};
