// 公開selectedは数値引数で、コ
// ンボ選択はselected引数でそれ
// ぞれ初期化する。確定時にコンボ選択
// を公開selectedへ反映する。
void NumberComboEditDialog::initialize(std::shared_ptr<::cw::lib::Window> arg_parent, ::cw::lib::String arg_title, ::cw::lib::String arg_label1, ::cw::lib::Value arg_mlist, ::cw::lib::Integer arg_selected, ::cw::lib::String arg_label2, ::cw::lib::Integer arg_value, ::cw::lib::Integer arg_minvalue, ::cw::lib::Integer arg_maxvalue, ::cw::lib::Integer arg_page)
{
    m_box1=arg_label1; m_combo=std::move(arg_mlist);
    const auto choices = choice_strings(m_combo);
    m_selected=arg_value;
    m_combo_selection=arg_selected >= 0 && arg_selected < static_cast<Integer>(choices.size()) ? arg_selected : -1;
    m_box2=arg_label2;
    m_slider=std::make_shared<NumberEditor>(); m_slider->initialize(nullptr,arg_value,arg_minvalue,arg_maxvalue,arg_page); m_value=arg_value;
    _do_layout(); _bind();
    EditUiSpec spec; spec.kind = EditUiKind::number_combo; spec.parent_handle = arg_parent ? arg_parent->native_handle : 0; spec.title = std::move(arg_title); spec.labels = {arg_label1, arg_label2}; spec.choices = choices; spec.choice_bitmaps = choice_bitmaps(m_combo); spec.values = {m_combo_selection, arg_value}; spec.minimums = {0, arg_minvalue}; spec.maximums = {std::max<Integer>(static_cast<Integer>(spec.choices.empty() ? 0 : spec.choices.size() - 1), 0), arg_maxvalue}; spec.pages = {0, arg_page};
    get_edit_ui_backend()->create(spec, [this](Integer action, const String& payload) {
        if (action == 0) OnCancel(nullptr);
        else if (action == 1) OnOk(nullptr);
        else if (action == 4) step_number_editor(m_slider, -1);
        else if (action == 5) step_number_editor(m_slider, 1);
        else if (action == 6) m_combo_selection = parse_event_integer(payload, m_combo_selection);
        else if (action == 8 && m_slider) m_slider->set_value(parse_event_integer(payload, m_value));
    });
}

