void BackColorEditDialog_OnOk_func(std::shared_ptr<::cw::character::Player> arg_ccard, std::tuple<::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer> arg_rgb)
{
    if (!arg_ccard || !arg_ccard->m_data_typed) return;
    auto color = arg_ccard->m_data_typed->find("Property/BackColor");
    if (!color || !*color) {
        auto property = arg_ccard->m_data_typed->find("Property");
        if ((!property || !*property) && arg_ccard->m_data_typed->getroot()) {
            arg_ccard->m_data_typed->getroot()->append(::cw::data::make_element("Property"));
            property = arg_ccard->m_data_typed->find("Property");
        }
        if (property && *property) { (*property)->append(::cw::data::make_element("BackColor")); color = (*property)->find("BackColor"); }
    }
    if (color && *color) {
        (*color)->set("r", std::to_string(std::get<0>(arg_rgb)));
        (*color)->set("g", std::to_string(std::get<1>(arg_rgb)));
        (*color)->set("b", std::to_string(std::get<2>(arg_rgb)));
        arg_ccard->m_data_typed->m_is_edited = true;
    }
}

SingleChoiceDialog::SingleChoiceDialog(String title, String message,
                                     std::vector<String> choices, int selected)
    : m_title(std::move(title)), m_message(std::move(message)), m_choices(std::move(choices))
{
    if (!m_choices.empty() && selected >= 0)
        m_selected = std::clamp(selected, 0, static_cast<int>(m_choices.size()) - 1);
    m_scroll = std::max(0, m_selected - 11);
}

::cw::dialog::DialogPresentation SingleChoiceDialog::dialog_presentation()
{
    using Action = ::cw::dialog::DialogPresentationAction;
    const auto s = [](int v) { return ::cw::lib::ui::win_i(v); };
    const int rows = std::clamp(static_cast<int>(m_choices.size()), 3, 12);
    const auto width = s(340), height = s(88 + rows * 24);
    auto& retained=dialog_retained_surface();
    const bool full=retained.needs_full({width,height});
    if(full) retained.allocate({width,height},{240,240,240,255});
    auto surface=retained.surface;
    ::cw::dialog::DialogPresentation p;
    p.route = "SingleChoice"; p.title = m_title; p.surface = surface;
    const auto font = ::cw::lib::ui::configured_font_scaled("dlgmsg", 14);
    if(full) ::cw::lib::ui::draw_label(surface, m_message, s(12), s(10), font.pixels,
                                      font.bold, {0, 0, 0}, font.face);
    const bool paged = static_cast<int>(m_choices.size()) > rows;
    const ::cw::lib::Rect list{s(10), s(34), s(paged ? 282 : 320), s(rows * 24 + 4)};
    if(full) {
        ::cw::lib::ui::fill_rect(surface, list, {255, 255, 255, 255});
        ::cw::lib::ui::draw_sunken_border(surface, list);
        retained.capture_base();
    }
    struct RowPaint {int index;::cw::lib::Rect rect;bool selected;bool changed;};
    std::vector<RowPaint> row_paints;
    for (int row = 0; row < rows && m_scroll + row < static_cast<int>(m_choices.size()); ++row) {
        const int index = m_scroll + row;
        const ::cw::lib::Rect rect{s(12), s(36 + row * 24), s(paged ? 278 : 316), s(24)};
        const bool selected = index == m_selected;
        const auto signature=(static_cast<std::uint64_t>(index+1)<<32U) ^
            (static_cast<std::uint64_t>(selected)<<16U) ^ static_cast<std::uint64_t>(m_finished);
        row_paints.push_back({index,rect,selected,retained.component_changed(
            "singlechoice.row."+std::to_string(row),rect,signature)});
        p.controls.push_back({Action::Select, index, static_cast<float>(rect.x), static_cast<float>(rect.y),
            static_cast<float>(rect.width), static_cast<float>(rect.height), !m_finished});
        p.controls.back().label = m_choices[index];
    }
    const auto button_font = ::cw::lib::ui::configured_font_scaled("button", 14);
    struct ButtonPaint {String label;::cw::lib::Rect rect;bool enabled;bool changed;};
    std::vector<ButtonPaint> button_paints;
    const auto button = [&](const String& label, int x, Action action, bool enabled,int component) {
        const ::cw::lib::Rect r{s(x), height - s(38), s(100), s(28)};
        button_paints.push_back({label,r,enabled,retained.component_changed(
            "singlechoice.button."+std::to_string(component),r,
            (static_cast<std::uint64_t>(enabled)<<1U)^static_cast<std::uint64_t>(m_finished))});
        p.controls.push_back({action, -1, static_cast<float>(r.x), static_cast<float>(r.y),
            static_cast<float>(r.width), static_cast<float>(r.height), enabled && !m_finished});
        p.controls.back().label = label;
        p.controls.back().hover_highlight = true;
    };
    button("OK", 116, Action::Accept, m_selected >= 0,0);
    button("キャンセル", 228, Action::Cancel, true,1);
    if (paged) {
        const auto pager = [&](const String& label, int y, Action action, bool enabled, int component) {
            const ::cw::lib::Rect r{s(298), s(y), s(32), s(32)};
            button_paints.push_back({label,r,enabled,retained.component_changed(
                "singlechoice.button."+std::to_string(component),r,
                (static_cast<std::uint64_t>(enabled)<<1U)^static_cast<std::uint64_t>(m_finished))});
            p.controls.push_back({action,-1,static_cast<float>(r.x),static_cast<float>(r.y),
                static_cast<float>(r.width),static_cast<float>(r.height),enabled && !m_finished});
            p.controls.back().label=label;
            p.controls.back().hover_highlight=true;
        };
        pager("▲", 34, Action::Previous, m_scroll > 0, 2);
        pager("▼", 34 + rows * 24 - 28, Action::Next,
              m_scroll < std::max(0, static_cast<int>(m_choices.size()) - rows), 3);
    }
    retained.restore_dirty();surface=retained.surface;
    const auto selection=::cw::lib::ui::system_selection_colours();
    for(const auto& paint:row_paints) if(paint.changed) {
        ::cw::lib::ui::fill_rect(surface,paint.rect,
            paint.selected ? selection.background : ::cw::lib::Color{255,255,255,255});
        ::cw::lib::ui::draw_label(surface,m_choices[paint.index],paint.rect.x+s(4),
            paint.rect.y+(paint.rect.height-font.pixels)/2,font.pixels,font.bold,
            paint.selected
                ? std::tuple<Integer,Integer,Integer>{selection.text.r,selection.text.g,selection.text.b}
                : std::tuple<Integer,Integer,Integer>{0,0,0},font.face);
    }
    for(const auto& paint:button_paints) if(paint.changed) {
        ::cw::lib::ui::fill_rect(surface,paint.rect,{240,240,240,255});
        ::cw::lib::ui::draw_button_face(surface,paint.rect,{paint.enabled});
        const auto tw=::cw::lib::ui::label_width(paint.label,button_font.pixels,button_font.bold,button_font.face);
        ::cw::lib::ui::draw_label(surface,paint.label,paint.rect.x+(paint.rect.width-tw)/2,
            paint.rect.y+(paint.rect.height-button_font.pixels)/2,button_font.pixels,button_font.bold,
            paint.enabled?std::tuple{0,0,0}:std::tuple{128,128,128},button_font.face);
    }
    retained.finish();p.surface=surface;p.damage=retained.damage;p.surface_revision=retained.revision;
    return p;
}

void SingleChoiceDialog::dialog_presentation_action(::cw::dialog::DialogPresentationAction action, int index)
{
    using Action = ::cw::dialog::DialogPresentationAction;
    if (m_finished) return;
    if ((action == Action::Select || action == Action::Activate) && index >= 0 && index < static_cast<int>(m_choices.size())) {
        m_selected = index;
        if (action == Action::Activate) { m_result = m_selected; m_finished = true; }
    } else if (action == Action::Accept && m_selected >= 0) {
        m_result = m_selected; m_finished = true;
    } else if (action == Action::Cancel) {
        m_result.reset(); m_finished = true;
    } else if (action == Action::Previous || action == Action::Next) {
        const int direction = action == Action::Previous ? -12 : 12;
        m_scroll = std::clamp(m_scroll + direction, 0,
            std::max(0, static_cast<int>(m_choices.size()) - 12));
    }
    request_dialog_presentation_refresh();
}

void SingleChoiceDialog::dialog_presentation_key(::cw::dialog::DialogPresentationKey key, bool pressed,
                                                ::cw::dialog::DialogPresentationModifiers modifiers)
{
    using Key = ::cw::dialog::DialogPresentationKey;
    using Action = ::cw::dialog::DialogPresentationAction;
    if (!pressed || m_finished || (modifiers & (::cw::dialog::DialogPresentationModifierControl |
                                               ::cw::dialog::DialogPresentationModifierAlt))) return;
    if (key == Key::Space || key == Key::Enter) { dialog_presentation_action(Action::Accept, -1); return; }
    if (key == Key::Backspace) { dialog_presentation_action(Action::Cancel, -1); return; }
    if (m_choices.empty()) return;
    if (key == Key::Up) --m_selected;
    else if (key == Key::Down) ++m_selected;
    else if (key == Key::PageUp) m_selected -= 12;
    else if (key == Key::PageDown) m_selected += 12;
    else if (key == Key::Home) m_selected = 0;
    else if (key == Key::End) m_selected = static_cast<int>(m_choices.size()) - 1;
    else return;
    m_selected = std::clamp(m_selected, 0, static_cast<int>(m_choices.size()) - 1);
    if (m_selected < m_scroll) m_scroll = m_selected;
    if (m_selected >= m_scroll + 12) m_scroll = m_selected - 11;
    request_dialog_presentation_refresh();
}

void SingleChoiceDialog::dialog_presentation_scroll(float x, float y, int lines)
{
    if (m_finished || lines == 0 || x < ::cw::lib::ui::win_i(10) || x >= ::cw::lib::ui::win_i(330) ||
        y < ::cw::lib::ui::win_i(34) || y >= ::cw::lib::ui::win_i(38 + std::clamp(static_cast<int>(m_choices.size()), 3, 12) * 24)) return;
    m_scroll = std::clamp(m_scroll + lines, 0, std::max(0, static_cast<int>(m_choices.size()) - 12));
    request_dialog_presentation_refresh();
}

